import { MakeLogicType, actions, afterMount, connect, kea, listeners, path, selectors } from 'kea'

import { addProjectIdIfMissing } from 'lib/utils/kea-router'

import { osAppSrc } from '../shell/osAppSrc'
import { osWindowsLogic } from '../windows/osWindowsLogic'
import { OsApp } from './osAppCatalog'
import { osInstalledAppsLogic } from './osInstalledAppsLogic'
import { readOsStoreMessage } from './osStoreMessages'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface osAppPreviewLogicValues {
    catalogApps: OsApp[] // osInstalledAppsLogic
    installedKeys: Set<string> // osInstalledAppsLogic
    previewBarApps: Record<string, OsApp>
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface osAppPreviewLogicActions {
    installApp: (key: string) => {
        key: string
    } // osInstalledAppsLogic
    openWindow: (
        path: string,
        options?: import('../windows/osWindowsLogic').OsOpenWindowOptions | undefined
    ) => {
        id: string
        options: import('../windows/osWindowsLogic').OsOpenWindowOptions
        path: string
    } // osWindowsLogic
    previewApp: (key: string) => {
        key: string
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface osAppPreviewLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        previewBarApps: (catalogApps: OsApp[], installedKeys: Set<string>) => Record<string, OsApp>
    }
}

export type osAppPreviewLogicType = MakeLogicType<
    osAppPreviewLogicValues,
    osAppPreviewLogicActions,
    Record<string, any>,
    osAppPreviewLogicMeta
>

/** App previews on the OS page: a marked window for an app that stays uninstalled. See the README. */
export const osAppPreviewLogic = kea<osAppPreviewLogicType>([
    path(['scenes', 'os', 'store', 'osAppPreviewLogic']),
    connect(() => ({
        values: [osInstalledAppsLogic, ['catalogApps', 'installedKeys']],
        actions: [osInstalledAppsLogic, ['installApp'], osWindowsLogic, ['openWindow']],
    })),
    actions({
        previewApp: (key: string) => ({ key }),
    }),
    selectors({
        previewBarApps: [
            (s) => [s.catalogApps, s.installedKeys],
            (catalogApps: OsApp[], installedKeys: Set<string>): Record<string, OsApp> =>
                Object.fromEntries(
                    catalogApps.filter((app) => !installedKeys.has(app.key)).map((app) => [app.key, app])
                ),
        ],
    }),
    listeners(({ actions, values }) => ({
        previewApp: ({ key }) => {
            // Only apps this user can see in the store, so a frame cannot preview a flag-gated app or a URL.
            const app = values.catalogApps.find((known) => known.key === key)
            // A path without the project id makes the OS page redirect its own address bar, which opens a second window.
            const src = app ? osAppSrc(addProjectIdIfMissing(app.href), window.location.origin) : null
            if (app && src) {
                actions.openWindow(src, { title: app.name, preview: app.key })
            }
        },
    })),
    afterMount(({ actions, cache }) => {
        cache.disposables.add(
            () => {
                const onMessage = (event: MessageEvent): void => {
                    const message = readOsStoreMessage(event)
                    if (message?.type === 'posthog-os-store:preview-app') {
                        actions.previewApp(message.key)
                    }
                }
                window.addEventListener('message', onMessage)
                return () => window.removeEventListener('message', onMessage)
            },
            'osStorePreviewMessages',
            { pauseOnPageHidden: false }
        )
    }),
])
